            continue

        if isinstance(value, str):
            value = re.sub(email_pattern, REPLACE_NONE, value)

        processed_data[key] = value

    value_counts = Counter(processed_data.values())

    return {
        "data": processed_data,
        "value_counts": value_counts
    }

